inputs.input:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:TransitiveShape a sh:NodeShape ;
  sh:targetNode ex:a ;
  sh:property [
    sh:path ex:edge+ ;
    sh:minCount 1
  ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape ;
  sh:targetClass ex:Person ;
  sh:property [
    sh:path ex:name ;
    sh:minCount 1
  ] .

SELECT ?person WHERE {
  ?person a ex:Person .
  FILTER NOT EXISTS { ?person ex:name ?name }
}

