inputs.input:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:PersonShape a sh:NodeShape ;
  sh:targetClass ex:Person ;
  sh:property [
    sh:path ex:email ;
    sh:pattern "^[a-z]+@[a-z]+\\.[a-z]+$"
  ] .

SELECT ?person ?email WHERE {
  ?person a ex:Person ; ex:email ?email .
  FILTER(!REGEX(?email, "^[a-z]+@[a-z]+\\.[a-z]+$"))
}

tests.dataGraph:
@prefix ex: <http://example.org/> .
ex:alice a ex:Person ; ex:email "alice@example.com" .
ex:bob a ex:Person ; ex:email "BOB@EXAMPLE.COM" .

inputs.input:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ex: <http://example.org/> .

ex:ResourceShape a sh:NodeShape ;
  sh:targetClass ex:Resource ;
  sh:property [
    sh:path ex:relatedTo ;
    sh:nodeKind sh:IRI
  ] .

SELECT ?resource ?value WHERE {
  ?resource a ex:Resource ; ex:relatedTo ?value .
  FILTER(!isIRI(?value))
}

